//  &lb,    &lb[/*lower_bound=*/0], sizeof(T*),    ATTACH




#pragma omp target map(lb[:X])
    {
#ifdef USE
      lb[4] += 1;
#endif
    }

// Region 02

//  [&this[0], &this[0].B, sizeof(B),     PARAM | ALLOC | IMPLICIT]
//  &B[0],     &B[X],      2 * sizeof(T), FROM
//  &B,        &B[X],      sizeof(T*),    ATTACH






#pragma omp target map(from \
